import{_ as e,o,c as d,a2 as r}from"./chunks/framework.D9E58p8B.js";const u=JSON.parse('{"title":"Touché (Touch)","description":"","frontmatter":{"title":"Touché (Touch)"},"headers":[],"relativePath":"en/reference/touche.md","filePath":"en/reference/touche.md"}'),s={name:"en/reference/touche.md"};function i(a,t,n,h,c,l){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="touche-touch-reading-the-accessibility-tree" tabindex="-1">Touché (Touch): reading the accessibility tree <a class="header-anchor" href="#touche-touch-reading-the-accessibility-tree" aria-label="Permalink to &quot;Touché (Touch): reading the accessibility tree&quot;">​</a></h1><p>Touché is the structural reading organ: it returns the elements of an interface (role, label, position) as the system exposes them through accessibility, redacted of sensitive content. The tool descriptions speak of the &quot;macOS accessibility tree&quot;. Both tools are read-only and are not subject to the Mains ceiling.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Role</th><th>Level</th></tr></thead><tbody><tr><td><a href="#touche-tree"><code>touche_tree</code></a></td><td>Bounded, redacted tree of a window</td><td>read</td></tr><tr><td><a href="#touche-probe"><code>touche_probe</code></a></td><td>Element located under a point on the screen</td><td>read</td></tr></tbody></table><p><strong>Prerequisite</strong>: the system Accessibility permission must be granted to the process responsible for Daimon. Without it, both tools return <code>accessibility_permission_denied</code>. <code>daimon_doctor</code> checks this permission without ever opening a dialog.</p><h2 id="erreurs-communes" tabindex="-1">Common errors <a class="header-anchor" href="#erreurs-communes" aria-label="Permalink to &quot;Common errors {#erreurs-communes}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Meaning</th></tr></thead><tbody><tr><td><code>accessibility_permission_denied</code></td><td>The Accessibility permission is missing</td></tr><tr><td><code>excluded</code></td><td>The target belongs to an application protected by your exclusions</td></tr><tr><td><code>snapshot_failed</code></td><td>Reading the tree failed</td></tr></tbody></table><h2 id="touche-tree" tabindex="-1">touche_tree <a class="header-anchor" href="#touche-tree" aria-label="Permalink to &quot;touche_tree {#touche-tree}&quot;">​</a></h2><p>Returns the accessibility tree, depth-bounded and redacted.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>max_depth</code></td><td>integer</td><td><code>4</code></td><td>no</td><td>Maximum depth of the traversal from the root</td></tr><tr><td><code>root</code></td><td>object <code>{x, y}</code></td><td>root of the foreground window</td><td>no</td><td>Point designating the root of the subtree</td></tr><tr><td><code>roles</code></td><td>list of strings</td><td>no filter</td><td>no</td><td>Filter by role; empty or omitted, no filter</td></tr><tr><td><code>prune_empty</code></td><td>boolean</td><td><code>true</code></td><td>no</td><td>Prunes empty or uninteresting nodes</td></tr><tr><td><code>summary</code></td><td>boolean</td><td><code>false</code></td><td>no</td><td>Returns a compact text summary rather than the node tree</td></tr><tr><td><code>window</code></td><td>object <code>{pid, bundle, title}</code></td><td>foreground window</td><td>no</td><td>Window target; each field is optional</td></tr></tbody></table><p><strong>Level</strong>: read.</p><p><strong>Example call</strong></p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;max_depth&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;roles&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AXButton&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;summary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;window&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;bundle&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;com.apple.finder&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p><strong>Returns</strong>: the redacted node tree, or <code>{summary}</code> (a string) when <code>summary</code> is true, or a contract error (see above).</p><p><strong>Pitfalls</strong></p><ul><li>A high depth on a rich application produces a very large response: prefer <code>summary</code>, <code>roles</code> or a targeted <code>root</code>.</li><li>Role values are those of the system accessibility; read them first from a full tree rather than guessing them.</li><li>An empty or silent tree (custom-drawn applications) is not an error: use <a href="./vue.html#vue-find"><code>vue_find</code></a> then.</li><li>Provide the <code>role</code> and <code>label</code> obtained this way to the Mains tools so that Daimon can check reversibility.</li></ul><h2 id="touche-probe" tabindex="-1">touche_probe <a class="header-anchor" href="#touche-probe" aria-label="Permalink to &quot;touche_probe {#touche-probe}&quot;">​</a></h2><p>Returns the single accessibility element located under a point on the screen, redacted.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Default</th><th>Required</th><th>Role</th></tr></thead><tbody><tr><td><code>x</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>X coordinate of the screen point</td></tr><tr><td><code>y</code></td><td>integer</td><td>none</td><td><strong>yes</strong></td><td>Y coordinate of the screen point</td></tr></tbody></table><p><strong>Level</strong>: read.</p><p><strong>Example call</strong>: <code>{ &quot;x&quot;: 640, &quot;y&quot;: 420 }</code></p><p><strong>Returns</strong>: the single redacted node, or a contract error (see above).</p><p><strong>Pitfalls</strong>: <code>x</code> and <code>y</code> are points of the global desktop, the same unit as that of <code>main_click</code>.</p>',22)])])}const g=e(s,[["render",i]]);export{u as __pageData,g as default};
